import {readFileSync} from 'node:fs';
import {SQLiteD1} from '../../sqlite-d1';
import {canonical,sha256} from '../../../src/lib/server/news-import/runtime/primitives';
import {NEWS_VERSION,EDITORIAL_REFERENCE} from '../../../src/lib/server/news-import/runtime/feed';
import {POLICY,registration,parseP3} from '../../../src/lib/server/news-import/runtime/registry';
import {bundleHash,validateBundle} from '../../../src/lib/server/news-import/runtime/bundle';

/** A small committed XML template; every derived record is explicitly fictional. */
export function fixtureBundle(number=1,options:{offset?:number;count?:number;revision?:string;xml?:string;source?:string}={}){
 const source=registration(options.source??'fixture-alpha').source,count=options.count??3;
 const items=Array.from({length:count},(_,n)=>`<item><guid>fiction-${(options.offset??0)+n}</guid><link>https://alpha.trace.test/fiction/${(options.offset??0)+n}?utm_source=fixture</link><title>Fictional test announcement ${(options.offset??0)+n}${options.revision??''}</title><pubDate>Sun, 25 Oct 2026 10:00:00 GMT</pubDate><description>Fictional source text retained exactly for offline provenance validation. No capability or execution compatibility is verified.</description></item>`).join('');
 const xml=options.xml??readFileSync('tests/fixtures/news-import/rss-template.xml','utf8').replace('{{ITEMS}}',items),parsed=parseP3(xml,source),source_hash=sha256(xml);
 const candidates=parsed.items.map(i=>({candidate_id:sha256(canonical({schema:NEWS_VERSION,item_id:i.item_id,content_hash:i.content_hash})),item_id:i.item_id,source,canonical_url:i.canonical_url,title:i.title,original_publication_date:i.published_raw,published_at:i.published_at,updated_at:i.updated_at,excerpt:i.excerpt,retrieved_at:'2026-10-25T12:00:00.000Z',source_hash,content_hash:i.content_hash,provenance:{schema:NEWS_VERSION,source_id:source.id,snapshot:`snapshots/news-p3/${source_hash}.xml`,locator:i.locator,reported_url:i.reported_url},duplicate_identity:{url_hash:i.url_hash,editorial_primary_source_key:`src:${i.url_hash}`,policy:EDITORIAL_REFERENCE.policy,scope:'exact-canonical-url-only'},declared_canonical_url:i.declared_canonical_url,declared_related_urls:i.declared_related_urls,quality_flags:i.quality_flags,review_required:true,verification_status:'unverified',admission_state:'unadmitted',publication_approved:false})).sort((a,b)=>a.item_id.localeCompare(b.item_id));
 const payload={schema:POLICY.schema,editorial_reference:POLICY.reference,adapter_status:POLICY.status,registry_version:POLICY.registry_version,candidates,pagination:{after:'',limit:candidates.length,next_cursor:null}},payload_json=canonical(payload)+'\n',package_id='TRACE-NEWS-P3-'+String(number).padStart(6,'0'),payload_sha256=sha256(payload_json),envelope_json=canonical({schema:'trace-news-envelope-p2.1',package_id,payload_sha256,bytes:Buffer.byteLength(payload_json),candidate_count:candidates.length,next_cursor:null})+'\n';
 const data={schema:'trace-news-import-bundle-p3.1' as const,package_id,payload_sha256,payload_json,envelope_json,snapshots:[{sha256:source_hash,xml}]},bundle={...data,bundle_sha256:bundleHash(data)};validateBundle(bundle,bundle.bundle_sha256);return bundle;
}
export const actor=()=>({email:'publisher@example.test',role:'publisher' as const,requestId:crypto.randomUUID()});
export function database(withMigration=true){const db=new SQLiteD1();db.countTriggerChanges=true;db.sqlite.exec('PRAGMA foreign_keys=ON');if(withMigration)db.sqlite.exec(readFileSync('db/migration-0080-local-news-import.sql','utf8'));for(const id of ['fixture-alpha','fixture-beta']){const r=registration(id);db.sqlite.prepare("INSERT INTO sources(id,name,url,feed_url,section,tier,treatment,ingestion_type,active) VALUES (?,?,?,?,'A','A','fixture-only','rss',0)").run(r.editorial_id,r.name,r.home,r.source.feed_url);}return db;}
export function counts(db:SQLiteD1){return Object.fromEntries(['editorial_candidates','news_import_packages','news_import_versions','news_import_proposals','news_import_deliveries','news_import_events','news_import_version_links','admin_audit_log','admin_request_nonces','feed_items','story_clusters'].map(t=>[t,db.sqlite.prepare('SELECT COUNT(*) n FROM '+t).get()!.n]));}
